import AppKit

/// The menubar icons: four status-tinted gauge PNGs (green/amber/red/grey)
/// generated by Scripts/gen_icons.swift and shipped as Core bundle resources.
/// NSImage(named:) resolves them from the app bundle directly — no runtime
/// image registration involved, which previously failed invisibly.
///
/// Icon colors were verified pixel-level: palette tinting collapsed some colors
/// (system colors → 0 alpha), so the generator owns the pixels explicitly.
public enum MenubarIcon {
    /// Status color name → image resource name.
    public static func imageName(_ statusColorName: String) -> String {
        "icon-\(statusColorName)"
    }

    /// Locates the Core resource bundle WITHOUT `Bundle.module`: its generated
    /// accessor aborts the process with an uncatchable fatal error whenever the
    /// bundle is absent (which crashed the installed app at first icon load).
    /// Order: explicit bundle in the app's Resources, then flattened Bundle.main
    /// resources (the build script copies the PNGs there as a fallback).
    public static var resourcesBundle: Bundle {
        if let cached = cachedResourcesBundle { return cached }
        let name = "AICreditPulse_AICreditPulseCore"
        if let url = Bundle.main.url(forResource: name, withExtension: "bundle"),
           let bundle = Bundle(url: url) {
            cachedResourcesBundle = bundle
            return bundle
        }
        cachedResourcesBundle = Bundle.main
        return Bundle.main
    }
    private static var cachedResourcesBundle: Bundle?

    /// Loads an icon and verifies it has visible (non-transparent) pixels.
    /// Handles both flattened (`process`) and nested (`copy`) resource layouts.
    public static func loadVerified(_ statusColorName: String) -> NSImage? {
        var url = resourcesBundle.url(forResource: imageName(statusColorName),
                                      withExtension: "png")
        if url == nil {
            url = resourcesBundle.url(forResource: imageName(statusColorName),
                                      withExtension: "png", subdirectory: "Resources")
        }
        guard let finalURL = url, let image = NSImage(contentsOf: finalURL) else { return nil }
        // Status bars need a non-template, named, accessibility-described image;
        // a template-flagged or anonymous image can render as nothing at all.
        image.isTemplate = false
        image.accessibilityDescription = "AI CreditPulse gauge"
        return image
    }

    /// Registers the four gauges into NSImage's named-image registry from the
    /// on-disk resources, so `NSImage(named:)` — which is what MenuBarExtra's
    /// label resolves through — finds them without depending on the app
    /// bundle's raw-resource lookup (SPM resource bundles are per-module, and
    /// the plain named lookup has repeatedly resolved to nothing here, which
    /// rendered as an invisible bar item). Also pins the size the status bar
    /// expects: an in-register 32pt image renders clipped or empty.
    @discardableResult
    public static func registerStatusBars() -> Int {
        var registered = 0
        for color in ["green", "amber", "red", "grey"] {
            guard let image = loadVerified(color) else { continue }
            image.size = NSSize(width: 18, height: 18)
            image.setName(imageName(color))
            registered += 1
        }
        return registered
    }
}
